1	\chapter{The \'etale plus construction of the relative Picard functor}
2	\label{chap:PicardEtale}
3	
4	For a curve \(C\) over \(k\) and an affine test scheme \(\Spec A\), the \'etale-sheafified
5	relative Picard group is computed by a single \emph{plus construction}: a class is represented
6	by a relative Picard class on an \'etale cover of \(\Spec A\) satisfying a descent condition,
7	and two representatives are identified when they agree on a common refinement. This chapter
8	constructs that plus, on affine test schemes indexed by a \(k\)-algebra \(A\); we recall from
9	elsewhere in this project the ambient functor it sheafifies. For an object \(T\) of
10	\(\Over(\Spec k)\) write \(\mathrm{relPic}(C,T)\) for the relative Picard group of \(C\) at
11	\(T\) --- the quotient of the Picard group of \(C \otimes T\) by the subgroup of classes pulled
12	back from \(T\) along the second projection --- a commutative group, with restriction
13	homomorphisms \(g^{*} \colon \mathrm{relPic}(C,T) \to \mathrm{relPic}(C,T')\) for a morphism
14	\(g \colon T' \to T\) of \(\Over(\Spec k)\), satisfying \((\id_T)^{*} = \id\) and
15	\((g \circ h)^{*} = h^{*} \circ g^{*}\). For a commutative \(k\)-algebra \(A\), write \(\Spec A\)
16	also for the object of \(\Over(\Spec k)\) it determines via the structure morphism
17	\(\Spec A \to \Spec k\) induced by the \(k\)-algebra structure of \(A\); a homomorphism of
18	\(k\)-algebras \(A \to A'\) induces, via \(\Spec\), a morphism \(\Spec A' \to \Spec A\) of
19	\(\Over(\Spec k)\). We abbreviate \(\mathrm{relPic}(C,A) := \mathrm{relPic}(C,\Spec A)\).
20	
21	\section{Presented \'etale covers of an affine scheme}
22	
23	Throughout this section \(A\) is a commutative ring (no field or \(k\)-algebra structure is
24	needed here). An \'etale cover of \(\Spec A\) in the sense consumed by the plus construction is
25	a faithfully flat \'etale \(A\)-algebra; to keep the index of covers of a fixed base
26	small --- which is what makes the plus construction below a legitimate colimit, rather than one
27	indexed by a proper class of isomorphism types --- we realize such algebras through an explicit
28	finite-variable presentation, at the cost of carrying a witness of the presentation as data.
29	
30	\begin{definition}[Presented \'etale cover]
31	  \label{def:etale_cover}
32	  \lean{Algebra.EtaleCover, Algebra.EtaleCover.Carrier}
33	  \leanok
34	  A \emph{presented \'etale cover} \(E\) of \(A\) consists of a natural number \(n\), an ideal
35	  \(I\) of the polynomial ring \(A[x_1,\dots,x_n]\), a proof that the quotient algebra
36	  \(B_E := A[x_1,\dots,x_n]/I\) is \'etale over \(A\), and a proof that the induced map of
37	  spectra \(\Spec B_E \to \Spec A\) is surjective. We call \(B_E\) the \emph{carrier} of \(E\).
38	  Since \'etale algebras are flat, surjectivity of \(\Spec B_E \to \Spec A\) together with
39	  flatness makes \(B_E\) faithfully flat over \(A\).
40	\end{definition}
41	
42	\begin{definition}[Presented covers from an \'etale algebra]
43	  \label{def:etale_cover_of}
44	  \lean{Algebra.EtaleCover.of}
45	  \uses{def:etale_cover}
46	  \leanok
47	  Let \(B\) be an \'etale \(A\)-algebra such that \(\Spec B \to \Spec A\) is surjective. Since
48	  \'etale algebras are of finite presentation, \(B\) admits a presentation as a quotient of a
49	  polynomial ring in finitely many variables over \(A\); choosing one such presentation
50	  produces a presented \'etale cover \(E\) of \(A\), denoted \(E = \mathrm{of}(B)\).
51	\end{definition}
52	
53	\begin{lemma}[Carrier of a presented cover from an algebra]
54	  \label{lem:etale_cover_ofEquiv}
55	  \lean{Algebra.EtaleCover.ofEquiv}
56	  \uses{def:etale_cover_of}
57	  \leanok
58	  In the situation of Definition~\ref{def:etale_cover_of}, the carrier \(B_E\) of
59	  \(E = \mathrm{of}(B)\) is isomorphic to \(B\) as an \(A\)-algebra.
60	\end{lemma}
61	\begin{proof}
62	  \leanok
63	  Immediate from the construction: \(E\) is built from a chosen presentation
64	  \(A[x_1,\dots,x_n] \twoheadrightarrow B\), and the carrier of the resulting cover is the
65	  quotient of \(A[x_1,\dots,x_n]\) by the kernel of that presentation, which is isomorphic to
66	  \(B\) by the first isomorphism theorem for algebras.
67	\end{proof}
68	
69	\begin{definition}[Refinement]
70	  \label{def:etale_cover_refines}
71	  \lean{Algebra.EtaleCover.Refines}
72	  \uses{def:etale_cover}
73	  \leanok
74	  For presented \'etale covers \(E, E'\) of \(A\), we say \(E'\) \emph{refines} \(E\) if there
75	  exists a homomorphism of \(A\)-algebras \(B_E \to B_{E'}\) (equivalently, a morphism
76	  \(\Spec B_{E'} \to \Spec B_E\) over \(\Spec A\)). This is a mere existence statement: no
77	  particular refinement map is remembered as data.
78	\end{definition}
79	
80	\begin{lemma}[Refinement is a preorder]
81	  \label{lem:etale_cover_refines_preorder}
82	  \lean{Algebra.EtaleCover.refines_refl, Algebra.EtaleCover.Refines.trans}
83	  \uses{def:etale_cover_refines}
84	  \leanok
85	  Every presented \'etale cover \(E\) of \(A\) refines itself, and if \(E''\) refines \(E'\)
86	  and \(E'\) refines \(E\) then \(E''\) refines \(E\).
87	\end{lemma}
88	\begin{proof}
89	  \leanok
90	  Reflexivity: the identity homomorphism of \(B_E\) witnesses that \(E\) refines itself.
91	  Transitivity: composing a homomorphism \(B_{E'} \to B_{E''}\) witnessing that \(E''\) refines
92	  \(E'\) with a homomorphism \(B_E \to B_{E'}\) witnessing that \(E'\) refines \(E\) gives a
93	  homomorphism \(B_E \to B_{E''}\) witnessing that \(E''\) refines \(E\).
94	\end{proof}
95	
96	\begin{definition}[Common refinement]
97	  \label{def:etale_cover_prod}
98	  \lean{Algebra.EtaleCover.prod, Algebra.EtaleCover.prodEquiv}
99	  \uses{def:etale_cover_of}
100	  \leanok
101	  For presented \'etale covers \(E, E'\) of \(A\), the \emph{common refinement} \(E \times E'\)
102	  is the presented \'etale cover of \(A\) with carrier \(B_E \otimes_A B_{E'}\) (\'etale over
103	  \(A\) because it is \'etale over the \'etale algebra \(B_E\), which is \'etale over \(A\); and
104	  faithfully flat by transitivity of faithfully flat extensions), obtained by applying
105	  Definition~\ref{def:etale_cover_of} to \(B_E \otimes_A B_{E'}\).
106	\end{definition}
107	
108	\begin{definition}[Coprojections of the common refinement]
109	  \label{def:etale_cover_prod_coproj}
110	  \lean{Algebra.EtaleCover.prodInl, Algebra.EtaleCover.prodInr}
111	  \uses{def:etale_cover_prod}
112	  \leanok
113	  The two canonical homomorphisms of \(A\)-algebras
114	  \(B_E \to B_{E \times E'} \cong B_E \otimes_A B_{E'}\), \(b \mapsto b \otimes 1\), and
115	  \(B_{E'} \to B_{E \times E'}\), \(b' \mapsto 1 \otimes b'\), transported along the carrier
116	  identification of Definition~\ref{def:etale_cover_prod}.
117	\end{definition}
118	
119	\begin{lemma}[The common refinement refines both factors]
120	  \label{lem:etale_cover_prod_refines}
121	  \lean{Algebra.EtaleCover.prod_refines_left, Algebra.EtaleCover.prod_refines_right}
122	  \uses{def:etale_cover_prod_coproj, def:etale_cover_refines}
123	  \leanok
124	  \(E \times E'\) refines both \(E\) and \(E'\).
125	\end{lemma}
126	\begin{proof}
127	  \leanok
128	  The two coprojections of Definition~\ref{def:etale_cover_prod_coproj} are homomorphisms of
129	  \(A\)-algebras out of \(B_E\), respectively \(B_{E'}\), witnessing the two refinements.
130	\end{proof}
131	
132	\begin{definition}[Universal map out of the common refinement]
133	  \label{def:etale_cover_prodLift}
134	  \lean{Algebra.EtaleCover.prodLift}
135	  \uses{def:etale_cover_prod}
136	  \leanok
137	  Given homomorphisms of \(A\)-algebras \(f \colon B_E \to B_F\) and \(g \colon B_{E'} \to
138	  B_F\), the induced homomorphism of \(A\)-algebras \(B_{E \times E'} \to B_F\), obtained from
139	  the universal property of the tensor product \(B_E \otimes_A B_{E'}\) applied to \(f\) and
140	  \(g\) (whose images commute in the commutative ring \(B_F\)), transported along the carrier
141	  identification of Definition~\ref{def:etale_cover_prod}.
142	\end{definition}
143	
144	\begin{lemma}[The universal map is a common section]
145	  \label{lem:etale_cover_prodLift_comp}
146	  \lean{Algebra.EtaleCover.prodLift_comp_prodInl, Algebra.EtaleCover.prodLift_comp_prodInr}
147	  \uses{def:etale_cover_prodLift, def:etale_cover_prod_coproj}
148	  \leanok
149	  In the situation of Definition~\ref{def:etale_cover_prodLift}, the induced map composed with
150	  each coprojection recovers the corresponding map: the composite \(B_E \to B_{E \times E'} \to
151	  B_F\) equals \(f\), and the composite \(B_{E'} \to B_{E \times E'} \to B_F\) equals \(g\).
152	\end{lemma}
153	\begin{proof}
154	  \leanok
155	  This is the defining property of the map induced by the universal property of the tensor
156	  product: on elementary tensors, \(b \otimes 1 \mapsto f(b) g(1) = f(b)\) and
157	  \(1 \otimes b' \mapsto f(1) g(b') = g(b')\).
158	\end{proof}
159	
160	\begin{theorem}[Directedness]
161	  \label{thm:etale_cover_exists_refines_prod}
162	  \lean{Algebra.EtaleCover.exists_refines_prod}
163	  \uses{def:etale_cover_refines}
164	  \leanok
165	  Any two presented \'etale covers \(E, E'\) of \(A\) admit a common refinement: there is a
166	  presented \'etale cover \(E''\) of \(A\) which refines both \(E\) and \(E'\).
167	\end{theorem}
168	\begin{proof}
169	  \leanok
170	  \uses{lem:etale_cover_prod_refines}
171	  Take \(E'' = E \times E'\); it refines both factors by Lemma~\ref{lem:etale_cover_prod_refines}.
172	\end{proof}
173	
174	\begin{definition}[The trivial cover]
175	  \label{def:etale_cover_self}
176	  \lean{Algebra.EtaleCover.self, Algebra.EtaleCover.selfEquiv}
177	  \uses{def:etale_cover_of}
178	  \leanok
179	  The presented \'etale cover of \(A\) by itself, obtained by applying
180	  Definition~\ref{def:etale_cover_of} to \(B = A\) (with structure morphism \(\Spec A \to
181	  \Spec A\) the identity, trivially surjective). Its carrier is isomorphic to \(A\).
182	\end{definition}
183	
184	\begin{definition}[Canonical map from the trivial cover]
185	  \label{def:etale_cover_fromSelf}
186	  \lean{Algebra.EtaleCover.fromSelf}
187	  \uses{def:etale_cover_self}
188	  \leanok
189	  For a presented \'etale cover \(E\) of \(A\), the canonical homomorphism of \(A\)-algebras
190	  from the carrier of the trivial cover to \(B_E\): under the identification of the carrier of
191	  the trivial cover with \(A\) (Definition~\ref{def:etale_cover_self}), the structure
192	  homomorphism \(A \to B_E\).
193	\end{definition}
194	
195	\begin{lemma}[Every cover refines the trivial cover]
196	  \label{lem:etale_cover_refines_self}
197	  \lean{Algebra.EtaleCover.refines_self}
198	  \uses{def:etale_cover_fromSelf, def:etale_cover_refines}
199	  \leanok
200	  Every presented \'etale cover \(E\) of \(A\) refines the trivial cover.
201	\end{lemma}
202	\begin{proof}
203	  \leanok
204	  The canonical map of Definition~\ref{def:etale_cover_fromSelf} witnesses the refinement.
205	\end{proof}
206	
207	\begin{definition}[Base change of a cover]
208	  \label{def:etale_cover_baseChange}
209	  \lean{Algebra.EtaleCover.baseChange, Algebra.EtaleCover.baseChangeEquiv}
210	  \uses{def:etale_cover_of}
211	  \leanok
212	  Let \(A'\) be a commutative \(A\)-algebra and \(E\) a presented \'etale cover of \(A\). The
213	  \emph{base change} \(E_{A'}\) is the presented \'etale cover of \(A'\) with carrier
214	  \(A' \otimes_A B_E\) (\'etale over \(A'\) and faithfully flat over \(A'\), both by base
215	  change of the corresponding properties of \(B_E\) over \(A\)), obtained by applying
216	  Definition~\ref{def:etale_cover_of} to \(A' \otimes_A B_E\).
217	\end{definition}
218	
219	\begin{definition}[Canonical inclusion into the base change]
220	  \label{def:etale_cover_baseChangeInclude}
221	  \lean{Algebra.EtaleCover.baseChangeInclude}
222	  \uses{def:etale_cover_baseChange}
223	  \leanok
224	  The canonical homomorphism of \(A\)-algebras \(\kappa_E \colon B_E \to B_{E_{A'}}\), which
225	  under the carrier identification \(B_{E_{A'}} \cong A' \otimes_A B_E\) of
226	  Definition~\ref{def:etale_cover_baseChange} is \(b \mapsto 1 \otimes b\).
227	\end{definition}
228	
229	\begin{definition}[Base change of a refinement map]
230	  \label{def:etale_cover_baseChangeMap}
231	  \lean{Algebra.EtaleCover.baseChangeMap}
232	  \uses{def:etale_cover_baseChange}
233	  \leanok
234	  For presented \'etale covers \(E, F\) of \(A\) and a homomorphism of \(A\)-algebras
235	  \(h \colon B_E \to B_F\), the induced homomorphism of \(A'\)-algebras \(B_{E_{A'}} \to
236	  B_{F_{A'}}\) which, under the carrier identifications of
237	  Definition~\ref{def:etale_cover_baseChange}, is \(\id_{A'} \otimes h\).
238	\end{definition}
239	
240	\begin{lemma}[Naturality of the canonical inclusion]
241	  \label{lem:etale_cover_baseChangeMap_comp_baseChangeInclude}
242	  \lean{Algebra.EtaleCover.baseChangeMap_comp_baseChangeInclude}
243	  \uses{def:etale_cover_baseChangeMap, def:etale_cover_baseChangeInclude}
244	  \leanok
245	  For \(h \colon B_E \to B_F\) as in Definition~\ref{def:etale_cover_baseChangeMap}, the square
246	  of \(A\)-algebra homomorphisms commutes: the composite \(B_E \to B_{E_{A'}} \to B_{F_{A'}}\)
247	  (canonical inclusion followed by the base-changed map) equals the composite
248	  \(B_E \to B_F \to B_{F_{A'}}\) (\(h\) followed by the canonical inclusion).
249	\end{lemma}
250	\begin{proof}
251	  \leanok
252	  Both composites send \(b \in B_E\) to \(1 \otimes h(b) \in A' \otimes_A B_F\) under the
253	  carrier identifications: the first computes \(b \mapsto 1 \otimes b \mapsto
254	  (\id_{A'}\otimes h)(1 \otimes b) = 1 \otimes h(b)\), and the second computes
255	  \(b \mapsto h(b) \mapsto 1 \otimes h(b)\).
256	\end{proof}
257	
258	\begin{lemma}[Nontrivial carrier]
259	  \label{lem:etale_cover_nontrivial_carrier}
260	  \lean{Algebra.EtaleCover.nontrivial_carrier}
261	  \uses{def:etale_cover}
262	  \leanok
263	  If \(A\) is a nontrivial ring, then the carrier \(B_E\) of any presented \'etale cover \(E\)
264	  of \(A\) is nontrivial.
265	\end{lemma}
266	\begin{proof}
267	  \leanok
268	  Since \(A\) is nontrivial, \(\Spec A\) is nonempty; since \(\Spec B_E \to \Spec A\) is
269	  surjective, \(\Spec B_E\) is nonempty, and a ring with nonempty spectrum is nontrivial.
270	\end{proof}
271	
272	\begin{theorem}[Field cofinality]
273	  \label{thm:etale_cover_field_cofinality}
274	  \lean{Algebra.EtaleCover.exists_finiteSeparableField_algHom}
275	  \uses{def:etale_cover}
276	  \leanok
277	  Let \(K\) be a field and \(E\) a presented \'etale cover of \(K\). Then there exist a field
278	  \(L\), finite and separable over \(K\), and a homomorphism of \(K\)-algebras
279	  \(B_E \to L\).
280	\end{theorem}
281	\begin{proof}
282	  \leanok
283	  \uses{lem:etale_cover_nontrivial_carrier}
284	  By the structure theorem for \'etale algebras over a field, \(B_E\) is isomorphic, as a
285	  \(K\)-algebra, to a finite product \(\prod_{i \in I} L_i\) of finite separable field
286	  extensions \(L_i\) of \(K\). By Lemma~\ref{lem:etale_cover_nontrivial_carrier}, \(B_E\) is
287	  nontrivial (\(K\) being a field is nontrivial), so the product is nonempty: \(I \neq
288	  \emptyset\), for the empty product is the zero ring. Choose \(i_0 \in I\) and set
289	  \(L = L_{i_0}\); the composite of the structure isomorphism with the projection onto the
290	  \(i_0\)-th factor is the required homomorphism \(B_E \to L\).
291	\end{proof}
292	
293	A finite separable field extension \(L\) of a field \(K\) is automatically \'etale over \(K\):
294	it is formally \'etale because it is formally unramified (separability) and formally smooth
295	(finiteness plus the algebra being a field, hence regular), and it is of finite presentation
296	because it is a finite-type algebra over a field which is moreover finite as a module.
297	
298	\begin{definition}[Field extension covers]
299	  \label{def:etale_cover_ofField}
300	  \lean{Algebra.EtaleCover.ofField, Algebra.EtaleCover.ofFieldEquiv}
301	  \uses{def:etale_cover_of}
302	  \leanok
303	  Let \(K\) be a field and \(L\) a finite separable field extension of \(K\). Since \(\Spec K\)
304	  is a single point, the spectrum map \(\Spec L \to \Spec K\) is trivially surjective, so
305	  Definition~\ref{def:etale_cover_of} applied to \(L\) produces a presented \'etale cover of
306	  \(K\) with carrier isomorphic to \(L\).
307	\end{definition}
308	
309	\section{The algebra-indexed relative Picard functor}
310	
311	In this section \(k\) is a field and \(C\) is an object of \(\Over(\Spec k)\).
312	
313	\begin{definition}[\(\Spec\) of an algebra map, as a morphism of test objects]
314	  \label{def:overSpecMap}
315	  \lean{AlgebraicGeometry.Over.overSpecMap}
316	  \leanok
317	  For commutative \(k\)-algebras \(A, B\) and a homomorphism of \(k\)-algebras
318	  \(f \colon A \to B\), the induced morphism \(\Spec B \to \Spec A\) of \(\Over(\Spec k)\):
319	  \(\Spec f\), which lies over \(\Spec k\) because \(f\) is a homomorphism of \(k\)-algebras.
320	\end{definition}
321	
322	\begin{lemma}[Functoriality of \(\Spec\) on algebra maps]
323	  \label{lem:overSpecMap_functor}
324	  \lean{AlgebraicGeometry.Over.overSpecMap_id, AlgebraicGeometry.Over.overSpecMap_comp}
325	  \uses{def:overSpecMap}
326	  \leanok
327	  \(\Spec\) of the identity homomorphism of \(A\) is the identity morphism of \(\Spec A\); and
328	  for homomorphisms of \(k\)-algebras \(f \colon A \to B\) and \(g \colon B \to C'\),
329	  \(\Spec(g \circ f) = \Spec f \circ \Spec g\) as morphisms \(\Spec C' \to \Spec A\).
330	\end{lemma}
331	\begin{proof}
332	  \leanok
333	  \(\Spec\) is a contravariant functor from commutative rings to schemes, so it sends the
334	  identity to the identity and a composite \(g \circ f\) to \(\Spec f \circ \Spec g\); the
335	  morphisms of \(\Over(\Spec k)\) so obtained are equal to the corresponding morphisms of
336	  schemes on their underlying data, so the identities transport.
337	\end{proof}
338	
339	\begin{definition}[Restriction of relative Picard classes along an algebra map]
340	  \label{def:relPicAlgMap}
341	  \lean{AlgebraicGeometry.relPicAlgMap}
342	  \uses{def:overSpecMap}
343	  \leanok
344	  For a homomorphism of \(k\)-algebras \(f \colon A \to B\), the induced homomorphism of groups
345	  \(f^{*} \colon \mathrm{relPic}(C,A) \to \mathrm{relPic}(C,B)\): restriction of relative
346	  Picard classes along the morphism \(\Spec f \colon \Spec B \to \Spec A\) of
347	  Definition~\ref{def:overSpecMap}.
348	\end{definition}
349	
350	\begin{lemma}[Functoriality in the algebra]
351	  \label{lem:relPicAlgMap_functor}
352	  \lean{AlgebraicGeometry.relPicAlgMap_id, AlgebraicGeometry.relPicAlgMap_comp}
353	  \uses{def:relPicAlgMap, lem:overSpecMap_functor}
354	  \leanok
355	  For every \(k\)-algebra \(A\), \((\id_A)^{*} = \id\) on \(\mathrm{relPic}(C,A)\); and for
356	  homomorphisms of \(k\)-algebras \(f \colon A \to B\) and \(g \colon B \to C'\),
357	  \((g \circ f)^{*} = g^{*} \circ f^{*}\) on \(\mathrm{relPic}(C,A)\). Thus
358	  \(A \mapsto \mathrm{relPic}(C,A)\), \(f \mapsto f^{*}\), is a covariant functor from
359	  \(k\)-algebras to commutative groups.
360	\end{lemma}
361	\begin{proof}
362	  \leanok
363	  Restriction of relative Picard classes along \(\Spec\) of a scheme morphism satisfies the
364	  functor laws \(\id^{*} = \id\) and \((\varphi \circ \psi)^{*} = \psi^{*} \circ \varphi^{*}\)
365	  in the morphism of \(\Over(\Spec k)\). Combined with
366	  Lemma~\ref{lem:overSpecMap_functor}, which shows \(\Spec\) of the identity algebra map is the
367	  identity morphism and \(\Spec\) of a composite \(g \circ f\) is \(\Spec f \circ \Spec g\), the
368	  two claimed identities for \(f^{*} := \Spec f{}^{*}\) follow.
369	\end{proof}
370	
371	\section{Descent classes on an \'etale cover}
372	
373	Throughout this section \(k\) is a field, \(C\) is an object of \(\Over(\Spec k)\), and \(A\) is
374	a commutative \(k\)-algebra. For a presented \'etale cover \(E\) of \(A\)
375	(Definition~\ref{def:etale_cover}) with carrier \(B_E\), the self-tensor product
376	\(B_E \otimes_A B_E\) is the carrier of the common refinement \(E \times E\) of \(E\) with
377	itself (Definition~\ref{def:etale_cover_prod}): it is the algebra of the \emph{double cover}
378	\(\Spec(B_E \otimes_A B_E) \to \Spec B_E\), whose two projections to \(\Spec B_E\) record the
379	overlap data of the cover \(E\).
380	
381	\begin{definition}[Coprojections of the double cover]
382	  \label{def:doubleInl_doubleInr}
383	  \lean{AlgebraicGeometry.doubleInl, AlgebraicGeometry.doubleInr}
384	  \uses{def:etale_cover}
385	  \leanok
386	  For a presented \'etale cover \(E\) of \(A\), the two homomorphisms of \(k\)-algebras
387	  \(B_E \to B_E \otimes_A B_E\), \(b \mapsto b \otimes 1\) and \(b \mapsto 1 \otimes b\) ---
388	  homomorphisms of \(A\)-algebras, in particular of \(k\)-algebras since \(A\) is a
389	  \(k\)-algebra.
390	\end{definition}
391	
392	\begin{definition}[Descent classes]
393	  \label{def:descentClasses}
394	  \lean{AlgebraicGeometry.descentClasses, AlgebraicGeometry.mem_descentClasses_iff}
395	  \uses{def:doubleInl_doubleInr, def:relPicAlgMap}
396	  \source{kleiman-picard}
397	  \leanok
398	  For a presented \'etale cover \(E\) of \(A\), the subgroup
399	  \(\mathrm{Desc}(C,E) \subseteq \mathrm{relPic}(C,B_E)\) of classes \(\lambda\) satisfying the
400	  \emph{descent condition}: the two pullbacks of \(\lambda\) along the coprojections of the
401	  double cover (Definition~\ref{def:doubleInl_doubleInr}) agree,
402	  \[
403	    \mathrm{Desc}(C,E) := \bigl\{\, \lambda \in \mathrm{relPic}(C,B_E) : \mathrm{inl}_E^{*}
404	    \lambda = \mathrm{inr}_E^{*} \lambda \text{ in } \mathrm{relPic}(C, B_E \otimes_A B_E)
405	    \,\bigr\},
406	  \]
407	  the equalizer of the two homomorphisms \(\mathrm{inl}_E^{*}, \mathrm{inr}_E^{*} \colon
408	  \mathrm{relPic}(C,B_E) \to \mathrm{relPic}(C, B_E \otimes_A B_E)\) of
409	  Definition~\ref{def:relPicAlgMap}, hence itself a subgroup.
410	\end{definition}
411	
412	\begin{lemma}[Naturality of the descent condition]
413	  \label{lem:relPicAlgMap_mem_descentClasses}
414	  \lean{AlgebraicGeometry.relPicAlgMap_mem_descentClasses}
415	  \uses{def:descentClasses}
416	  \leanok
417	  Let \(E, F\) be presented \'etale covers of \(A\) and \(h \colon B_E \to B_F\) a
418	  homomorphism of \(A\)-algebras. If \(\lambda \in \mathrm{Desc}(C,E)\), then
419	  \(h^{*}\lambda \in \mathrm{Desc}(C,F)\).
420	\end{lemma}
421	\begin{proof}
422	  \leanok
423	  \uses{lem:relPicAlgMap_functor}
424	  The homomorphism \(h \otimes h \colon B_E \otimes_A B_E \to B_F \otimes_A B_F\) intertwines
425	  the coprojections: \(\mathrm{inl}_F \circ h = (h \otimes h) \circ \mathrm{inl}_E\) and
426	  \(\mathrm{inr}_F \circ h = (h \otimes h) \circ \mathrm{inr}_E\), since both sides send
427	  \(b \mapsto h(b) \otimes 1\), respectively \(b \mapsto 1 \otimes h(b)\). By functoriality
428	  (Lemma~\ref{lem:relPicAlgMap_functor}),
429	  \[
430	    \mathrm{inl}_F^{*}(h^{*}\lambda) = (h \otimes h)^{*}(\mathrm{inl}_E^{*}\lambda)
431	    = (h \otimes h)^{*}(\mathrm{inr}_E^{*}\lambda) = \mathrm{inr}_F^{*}(h^{*}\lambda),
432	  \]
433	  using \(\lambda \in \mathrm{Desc}(C,E)\) in the middle equality. Hence
434	  \(h^{*}\lambda \in \mathrm{Desc}(C,F)\).
435	\end{proof}
436	
437	\begin{definition}[Transport of descent classes]
438	  \label{def:descentMap}
439	  \lean{AlgebraicGeometry.descentMap}
440	  \uses{lem:relPicAlgMap_mem_descentClasses}
441	  \leanok
442	  For \(h \colon B_E \to B_F\) a homomorphism of \(A\)-algebras between the carriers of two
443	  presented \'etale covers of \(A\), the induced homomorphism of groups \(h_{*} \colon
444	  \mathrm{Desc}(C,E) \to \mathrm{Desc}(C,F)\), \(\lambda \mapsto h^{*}\lambda\), well-defined by
445	  Lemma~\ref{lem:relPicAlgMap_mem_descentClasses}.
446	\end{definition}
447	
448	\begin{lemma}[Transport along the identity]
449	  \label{lem:descentMap_id}
450	  \lean{AlgebraicGeometry.descentMap_id}
451	  \uses{def:descentMap}
452	  \leanok
453	  For every presented \'etale cover \(E\) of \(A\), transport along the identity homomorphism
454	  of \(B_E\) is the identity on \(\mathrm{Desc}(C,E)\).
455	\end{lemma}
456	\begin{proof}
457	  \leanok
458	  \uses{lem:relPicAlgMap_functor}
459	  Immediate from \((\id_{B_E})^{*} = \id\) (Lemma~\ref{lem:relPicAlgMap_functor}).
460	\end{proof}
461	
462	\begin{lemma}[Transport is functorial]
463	  \label{lem:descentMap_comp}
464	  \lean{AlgebraicGeometry.descentMap_comp}
465	  \uses{def:descentMap}
466	  \leanok
467	  For homomorphisms of \(A\)-algebras \(h \colon B_E \to B_F\) and \(h' \colon B_F \to B_G\)
468	  between carriers of presented \'etale covers of \(A\), transport along \(h' \circ h\) equals
469	  transport along \(h'\) followed by transport along \(h\): \((h' \circ h)_{*} = h'_{*} \circ
470	  h_{*}\) on \(\mathrm{Desc}(C,E)\).
471	\end{lemma}
472	\begin{proof}
473	  \leanok
474	  \uses{lem:relPicAlgMap_functor}
475	  Immediate from \((h' \circ h)^{*} = h'^{*} \circ h^{*}\) (Lemma~\ref{lem:relPicAlgMap_functor}),
476	  restricted to \(\mathrm{Desc}(C,E)\).
477	\end{proof}
478	
479	\begin{theorem}[Refinement independence, the keystone]
480	  \label{thm:relPicAlgMap_congr}
481	  \lean{AlgebraicGeometry.relPicAlgMap_congr}
482	  \uses{def:descentClasses}
483	  \leanok
484	  Let \(E\) be a presented \'etale cover of \(A\) with carrier \(B = B_E\), let \(R\) be a
485	  commutative \(k\)-algebra equipped with a compatible \(A\)-algebra structure (so that
486	  \(k \to A \to R\) is a tower of algebras), and let \(j_1, j_2 \colon B \to R\) be two
487	  homomorphisms of \(A\)-algebras. If \(\lambda \in \mathrm{Desc}(C,E)\), then
488	  \(j_1^{*}\lambda = j_2^{*}\lambda\) in \(\mathrm{relPic}(C,R)\).
489	\end{theorem}
490	\begin{proof}
491	  \leanok
492	  \uses{lem:relPicAlgMap_functor}
493	  Let \(H \colon B \otimes_A B \to R\) be the homomorphism of \(A\)-algebras induced by the
494	  universal property of the tensor product from the pair \((j_1, j_2)\) (their images commute
495	  in the commutative ring \(R\)): \(H(b \otimes b') = j_1(b) j_2(b')\). Then
496	  \(H \circ \mathrm{inl}_E = j_1\) (since \(H(b \otimes 1) = j_1(b) j_2(1) = j_1(b)\)) and
497	  \(H \circ \mathrm{inr}_E = j_2\) (since \(H(1 \otimes b) = j_1(1) j_2(b) = j_2(b)\)). By
498	  functoriality (Lemma~\ref{lem:relPicAlgMap_functor}),
499	  \[
500	    j_1^{*}\lambda = H^{*}(\mathrm{inl}_E^{*}\lambda) = H^{*}(\mathrm{inr}_E^{*}\lambda)
501	    = j_2^{*}\lambda,
502	  \]
503	  using \(\lambda \in \mathrm{Desc}(C,E)\), i.e. \(\mathrm{inl}_E^{*}\lambda =
504	  \mathrm{inr}_E^{*}\lambda\), in the middle equality.
505	\end{proof}
506	
507	\begin{theorem}[Refinement-map independence]
508	  \label{thm:descentMap_congr}
509	  \lean{AlgebraicGeometry.descentMap_congr}
510	  \uses{thm:relPicAlgMap_congr, def:descentMap}
511	  \leanok
512	  Let \(E, F\) be presented \'etale covers of \(A\) and \(h_1, h_2 \colon B_E \to B_F\) two
513	  homomorphisms of \(A\)-algebras. Then \(h_{1,*} = h_{2,*}\) as maps
514	  \(\mathrm{Desc}(C,E) \to \mathrm{Desc}(C,F)\): transport of a descent class along \(h_1\) and
515	  along \(h_2\) always agree.
516	\end{theorem}
517	\begin{proof}
518	  \leanok
519	  Apply Theorem~\ref{thm:relPicAlgMap_congr} with \(R = B_F\) (an \(A\)-algebra which is also a
520	  \(k\)-algebra compatibly, since \(F\) is a cover of the \(k\)-algebra \(A\)), \(j_1 = h_1\),
521	  \(j_2 = h_2\).
522	\end{proof}
