740	\begin{definition}[Inverse]
741	  \label{def:PicEtAff_inv}
742	  \lean{AlgebraicGeometry.PicEtAff.instInv, AlgebraicGeometry.PicEtAff.mk_inv}
743	  \uses{def:PicEtAff_mk, def:picEtAffSetoid}
744	  \leanok
745	  \(\mathrm{PicEtAff}(C,A)\) carries an inversion, defined on representatives by
746	  \([E,\lambda]^{-1} = [E,\lambda^{-1}]\); well-defined because if \((E,\lambda) \sim (F,\mu)\)
747	  via \((G,f,g)\), so \(f_{*}\lambda = g_{*}\mu\), then applying the group homomorphism
748	  \(f_{*}\), respectively \(g_{*}\), to inverses gives \(f_{*}(\lambda^{-1}) =
749	  (f_{*}\lambda)^{-1} = (g_{*}\mu)^{-1} = g_{*}(\mu^{-1})\), so \((E,\lambda^{-1}) \sim
750	  (F,\mu^{-1})\) via the same \((G,f,g)\).
751	\end{definition}
752	
753	\begin{theorem}[\(\mathrm{PicEtAff}(C,A)\) is a commutative group]
754	  \label{thm:PicEtAff_commGroup}
755	  \lean{AlgebraicGeometry.PicEtAff.instCommGroup}
756	  \uses{thm:PicEtAff_mk_mul_mk_same, thm:PicEtAff_mk_one, def:PicEtAff_inv,
757	    lem:PicEtAff_ind, lem:PicEtAff_mk_descentMap, def:etale_cover_prod_coproj}
758	  \leanok
759	  With the multiplication of Theorem~\ref{thm:PicEtAff_mk_mul_mk}, the identity of
760	  Definition~\ref{def:PicEtAff_one}, and the inversion of Definition~\ref{def:PicEtAff_inv},
761	  \(\mathrm{PicEtAff}(C,A)\) is a commutative group.
762	\end{theorem}
763	\begin{proof}
764	  \leanok
765	  By Lemma~\ref{lem:PicEtAff_ind} every element is of the form \([E,\lambda]\), so it suffices
766	  to check the axioms on such representatives, re-expressing every class involved as a class on
767	  one common cover by Lemma~\ref{lem:PicEtAff_mk_descentMap} (transporting a representative up
768	  along a chosen refinement map does not change its plus class) and then applying
769	  Theorem~\ref{thm:PicEtAff_mk_mul_mk_same} to compute products of classes living on the same
770	  cover.
771	
772	  \emph{Associativity.} For \(a = [E,\lambda]\), \(b = [F,\mu]\), \(c = [G,\nu]\), rewrite
773	  \(a\), \(b\), \(c\) as classes on the common cover \((E \times F) \times G\), transporting
774	  \(\lambda\) along \(\mathrm{inl}_{E \times F, G} \circ \mathrm{inl}_{E,F}\), \(\mu\) along
775	  \(\mathrm{inl}_{E \times F, G} \circ \mathrm{inr}_{E,F}\), and \(\nu\) along
776	  \(\mathrm{inr}_{E \times F, G}\) (Lemma~\ref{lem:PicEtAff_mk_descentMap}); the three

